#ifndef KERNEL_H
#define KERNEL_H

#include <ap_fixed.h>
#include <ap_int.h>
#include <hls_math.h>

// Fixed-point type: 46 total bits, 28 fractional bits
typedef ap_fixed<46, 18> fixed_t;

// Complex fixed-point struct
struct complex_t {
    fixed_t re;
    fixed_t im;
};

// Matrix/vector dimensions
static const int N = 10;

// Top-level kernel
// Inputs:
//   A       : N x N complex matrix (row-major, flattened)
//   max_iter: maximum number of Jacobi iterations
// Outputs:
//   out_iter: iteration index at which convergence occurred (or max_iter-1)
//   eigenvalues: N complex values (diagonal of A after convergence)
//   eigenvectors: N x N complex matrix V (row-major, flattened)
void kernel_top(
    complex_t  A_in[N * N],
    int        max_iter,
    int       *out_iter,
    complex_t  eigenvalues[N],
    complex_t  eigenvectors[N * N]
);

#endif // KERNEL_H
