#include "kernel.h"
#include <hls_math.h>

// ---------------------------------------------------------------------------
// Helper: magnitude squared of a complex number
// ---------------------------------------------------------------------------
static fixed_t cabs2(complex_t a) {
#pragma HLS INLINE
    return a.re * a.re + a.im * a.im;
}

// ---------------------------------------------------------------------------
// Helper: magnitude of a complex number (sqrt of abs2)
// ---------------------------------------------------------------------------
static fixed_t cabs_val(complex_t a) {
#pragma HLS INLINE
    fixed_t s = a.re * a.re + a.im * a.im;
    return hls::sqrt((float)s);
}

// ---------------------------------------------------------------------------
// Helper: multiply two complex numbers
// ---------------------------------------------------------------------------
static complex_t cmul(complex_t a, complex_t b) {
#pragma HLS INLINE
    complex_t r;
    r.re = a.re * b.re - a.im * b.im;
    r.im = a.re * b.im + a.im * b.re;
    return r;
}

// ---------------------------------------------------------------------------
// Helper: conjugate of a complex number
// ---------------------------------------------------------------------------
static complex_t cconj(complex_t a) {
#pragma HLS INLINE
    complex_t r;
    r.re =  a.re;
    r.im = -a.im;
    return r;
}

// ---------------------------------------------------------------------------
// Helper: add two complex numbers
// ---------------------------------------------------------------------------
static complex_t cadd(complex_t a, complex_t b) {
#pragma HLS INLINE
    complex_t r;
    r.re = a.re + b.re;
    r.im = a.im + b.im;
    return r;
}

// ---------------------------------------------------------------------------
// kernel_top
// ---------------------------------------------------------------------------
void kernel_top(
    complex_t  A_in[N * N],
    int        max_iter,
    int       *out_iter,
    complex_t  eigenvalues[N],
    complex_t  eigenvectors[N * N]
) {
#pragma HLS INTERFACE ap_none port=A_in
#pragma HLS INTERFACE ap_none port=max_iter
#pragma HLS INTERFACE ap_none port=out_iter
#pragma HLS INTERFACE ap_none port=eigenvalues
#pragma HLS INTERFACE ap_none port=eigenvectors
#pragma HLS INTERFACE ap_ctrl_none port=return

    // Working copies of A and V
    complex_t A[N][N];
    complex_t V[N][N];

    // Initialise A from flat input, V = I
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            A[i][j] = A_in[i * N + j];
            complex_t id;
            id.re = (i == j) ? fixed_t(1) : fixed_t(0);
            id.im = fixed_t(0);
            V[i][j] = id;
        }
    }

    int z = 0;

    // ---------- main Jacobi loop ----------
    for (int iter = 0; iter < 2000; iter++) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=2000

        if (iter >= max_iter) {
            z = iter - 1;
            break;
        }

        // --- find pivot (p,q) with largest |A[i][j]|, i<j ---
        float off_max = 0.0f;
        int   p = 0, q = 1;

        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
#pragma HLS PIPELINE II=1
                float mag = (float)cabs_val(A[i][j]);
                if (mag > off_max) {
                    off_max = mag;
                    p = i;
                    q = j;
                }
            }
        }

        // --- convergence check ---
        if (off_max < 1e-6f) {
            z = iter;
            goto done;
        }
        z = iter;

        // --- compute rotation parameters ---
        // a_pp, a_qq are real on the diagonal (but stored as complex)
        float a_pp_r = (float)A[p][p].re;
        float a_qq_r = (float)A[q][q].re;
        float a_pq_r = (float)A[p][q].re;
        float a_pq_i = (float)A[p][q].im;

        float a_pq_abs = hls::sqrt(a_pq_r * a_pq_r + a_pq_i * a_pq_i);
        float denom    = a_pp_r - a_qq_r;

        float theta;
        if (hls::fabs(denom) < 1e-12f) {
            theta = 3.14159265358979323846f / 4.0f; // pi/4
        } else {
            theta = 0.5f * hls::atan(2.0f * a_pq_abs / denom);
        }

        // phi = -angle(a_pq)
        float phi = -hls::atan2(a_pq_i, a_pq_r);

        float cos_th = hls::cos(theta);
        float sin_th = hls::sin(theta);
        float cos_ph = hls::cos(phi);
        float sin_ph = hls::sin(phi);

        // U[p][p] =  cos(theta)
        // U[p][q] =  sin(theta)*exp(-j*phi) = sin_th*(cos_ph - j*sin_ph)
        // U[q][p] =  sin(theta)*exp( j*phi) = sin_th*(cos_ph + j*sin_ph)
        // U[q][q] = -cos(theta)

        complex_t U_pp, U_pq, U_qp, U_qq;
        U_pp.re =  (fixed_t)cos_th;  U_pp.im = (fixed_t)0.0f;
        U_pq.re =  (fixed_t)(sin_th * cos_ph);  U_pq.im = (fixed_t)(-sin_th * sin_ph);
        U_qp.re =  (fixed_t)(sin_th * cos_ph);  U_qp.im = (fixed_t)( sin_th * sin_ph);
        U_qq.re = -(fixed_t)cos_th;  U_qq.im = (fixed_t)0.0f;

        // conjugates for U^H columns
        complex_t Uc_pp = cconj(U_pp);  // conj of U[p][p]
        complex_t Uc_qp = cconj(U_pq);  // conj of U[p][q]  -> row p of U^H col q
        complex_t Uc_pq = cconj(U_qp);  // conj of U[q][p]  -> row q of U^H col p
        complex_t Uc_qq = cconj(U_qq);  // conj of U[q][q]

        // --- A  <-  U^H * A * U ---
        // Step 1: B = U^H * A  (only rows p and q change)
        complex_t B[N][N];

        // Copy rows that don't change
        for (int i = 0; i < N; i++) {
            if (i == p || i == q) continue;
            for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
                B[i][j] = A[i][j];
            }
        }

        // Rows p and q of B
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            // B[p][j] = conj(U[p][p])*A[p][j] + conj(U[q][p])*A[q][j]
            B[p][j] = cadd(cmul(Uc_pp, A[p][j]), cmul(Uc_pq, A[q][j]));
            // B[q][j] = conj(U[p][q])*A[p][j] + conj(U[q][q])*A[q][j]
            B[q][j] = cadd(cmul(Uc_qp, A[p][j]), cmul(Uc_qq, A[q][j]));
        }

        // Step 2: A = B * U  (only cols p and q change)
        // Copy cols that don't change
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (j == p || j == q) continue;
#pragma HLS PIPELINE II=1
                A[i][j] = B[i][j];
            }
        }

        // Cols p and q of A
        for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
            // A[i][p] = B[i][p]*U[p][p] + B[i][q]*U[q][p]
            A[i][p] = cadd(cmul(B[i][p], U_pp), cmul(B[i][q], U_qp));
            // A[i][q] = B[i][p]*U[p][q] + B[i][q]*U[q][q]
            A[i][q] = cadd(cmul(B[i][p], U_pq), cmul(B[i][q], U_qq));
        }

        // Zero out pivot elements
        A[p][q].re = fixed_t(0); A[p][q].im = fixed_t(0);
        A[q][p].re = fixed_t(0); A[q][p].im = fixed_t(0);

        // --- V <- V * U  (only cols p and q change) ---
        complex_t Vp[N], Vq[N];
        for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
            Vp[i] = cadd(cmul(V[i][p], U_pp), cmul(V[i][q], U_qp));
            Vq[i] = cadd(cmul(V[i][p], U_pq), cmul(V[i][q], U_qq));
        }
        for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
            V[i][p] = Vp[i];
            V[i][q] = Vq[i];
        }
    }

done:
    // --- write outputs ---
    *out_iter = z;

    for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
        eigenvalues[i] = A[i][i];
    }

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            eigenvectors[i * N + j] = V[i][j];
        }
    }
}
