// Testbench: runs call index 0 from captured IO vectors.
// Input files  : ../eig_10_io/in_A.txt          (complex: interleaved re im per line pair, 10x10=100 elements)
//                ../eig_10_io/in_max_iter.txt    (scalar integer, one value per call)
// Output files : sim/out_0.txt   (scalar int)
//                sim/out_1.txt   (10 complex values, interleaved re im)
//                sim/out_2.txt   (100 complex values, interleaved re im)

#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <cstring>
#include "kernel.h"

static const int CALL_IDX = 0;  // only run index 0

// ---------------------------------------------------------------------------
// Read `count` complex scalars (interleaved re im on separate lines) into buf
// starting at `offset`-th element in the file.
// Format expected: each element occupies two lines: "re\n" then "im\n".
// ---------------------------------------------------------------------------
static int read_complex_vec(const char *path, int offset, int count, complex_t *buf) {
    FILE *f = fopen(path, "r");
    if (!f) { fprintf(stderr, "Cannot open %s\n", path); return -1; }

    // Skip `offset * 2` lines
    char line[256];
    for (int k = 0; k < offset * 2; k++) {
        if (!fgets(line, sizeof(line), f)) { fclose(f); return -1; }
    }

    for (int k = 0; k < count; k++) {
        double re = 0.0, im = 0.0;
        // Try reading as "re im" on one line first, then fall back to two lines
        if (!fgets(line, sizeof(line), f)) { fclose(f); return -1; }
        int n_tok = sscanf(line, "%lf %lf", &re, &im);
        if (n_tok == 1) {
            // imaginary part is on the next line
            if (!fgets(line, sizeof(line), f)) { fclose(f); return -1; }
            sscanf(line, "%lf", &im);
        }
        buf[k].re = (fixed_t)re;
        buf[k].im = (fixed_t)im;
    }
    fclose(f);
    return 0;
}

// ---------------------------------------------------------------------------
// Read one int64 scalar at position `offset` in the file.
// ---------------------------------------------------------------------------
static int read_int_scalar(const char *path, int offset, int *out) {
    FILE *f = fopen(path, "r");
    if (!f) { fprintf(stderr, "Cannot open %s\n", path); return -1; }

    char line[256];
    for (int k = 0; k <= offset; k++) {
        if (!fgets(line, sizeof(line), f)) { fclose(f); return -1; }
        if (k == offset) {
            long long v = 0;
            sscanf(line, "%lld", &v);
            *out = (int)v;
        }
    }
    fclose(f);
    return 0;
}

// ---------------------------------------------------------------------------
// Write a single integer to a file.
// ---------------------------------------------------------------------------
static void write_int_scalar(const char *path, int val) {
    FILE *f = fopen(path, "w");
    if (!f) { fprintf(stderr, "Cannot open %s for write\n", path); return; }
    fprintf(f, "%d\n", val);
    fclose(f);
}

// ---------------------------------------------------------------------------
// Write `count` complex values (interleaved re im, one value per line pair).
// ---------------------------------------------------------------------------
static void write_complex_vec(const char *path, const complex_t *buf, int count) {
    FILE *f = fopen(path, "w");
    if (!f) { fprintf(stderr, "Cannot open %s for write\n", path); return; }
    for (int k = 0; k < count; k++) {
        fprintf(f, "%.17g %.17g\n", (double)(float)buf[k].re, (double)(float)buf[k].im);
    }
    fclose(f);
}

// ---------------------------------------------------------------------------
// main
// ---------------------------------------------------------------------------
int main(void) {
    // --- Input buffers ---
    static complex_t A_in[N * N];
    int max_iter_val = 2000;

    // --- Output buffers ---
    int       out_iter  = 0;
    static complex_t eigenvalues[N];
    static complex_t eigenvectors[N * N];

    // --- Read inputs for call index 0 ---
    if (read_complex_vec("../eig_10_io/in_A.txt",
                         CALL_IDX * N * N, N * N, A_in) != 0) {
        fprintf(stderr, "Failed to read A\n");
        return 1;
    }

    if (read_int_scalar("../eig_10_io/in_max_iter.txt",
                        CALL_IDX, &max_iter_val) != 0) {
        fprintf(stderr, "Failed to read max_iter, using default 2000\n");
        max_iter_val = 2000;
    }

    printf("Running kernel_top with max_iter=%d ...\n", max_iter_val);

    // --- Invoke kernel ---
    kernel_top(A_in, max_iter_val, &out_iter, eigenvalues, eigenvectors);

    printf("kernel_top finished: out_iter=%d\n", out_iter);

    // --- Write outputs ---
    write_int_scalar("sim/out_0.txt", out_iter);
    write_complex_vec("sim/out_1.txt", eigenvalues, N);
    write_complex_vec("sim/out_2.txt", eigenvectors, N * N);

    printf("Outputs written to sim/out_0.txt, sim/out_1.txt, sim/out_2.txt\n");
    return 0;
}
